function wordPattern(pattern: string, s: string): boolean {
  const words = s.split(' ');

  // Количество букв и слов должно совпадать
  if (words.length !== pattern.length) return false;

  // Отображения в обе стороны: буква -> слово и слово -> буква
  const charToWord = new Map<string, string>();
  const wordToChar = new Map<string, string>();

  for (let i = 0; i < pattern.length; i++) {
    const c = pattern[i];
    const w = words[i];

    const mappedWord = charToWord.get(c);
    const mappedChar = wordToChar.get(w);

    // Буква уже связана с другим словом
    if (mappedWord !== undefined && mappedWord !== w) return false;
    // Слово уже связано с другой буквой
    if (mappedChar !== undefined && mappedChar !== c) return false;

    charToWord.set(c, w);
    wordToChar.set(w, c);
  }

  return true;
}

// Время: O(n + m), где n — длина pattern, m — длина s
// Память: O(n + m) — слова и две таблицы
